type Navigate = (path: string) => void;
const formatRoute = (path: string) => path === "/" ? "/" : path.replace(/\/+$/, "");
const singaporeModes: { label: string; value: ListingMode }[] = [{ label: "Buy", value: "Buy" }, { label: "Rent", value: "Rent" }, { label: "Sell", value: "Sell" }, { label: "Rent out", value: "Rent-Out" }];
const marketNames: Record<MarketId, string> = { singapore: "Singapore", indonesia: "Indonesia", malaysia: "Malaysia", thailand: "Thailand", vietnam: "Vietnam", philippines: "Philippines" };

function useRoute() {
  const [route, setRoute] = useState(() => ({ path: formatRoute(window.location.pathname), search: window.location.search }));
  useEffect(() => { const update = () => setRoute({ path: formatRoute(window.location.pathname), search: window.location.search }); window.addEventListener("popstate", update); return () => window.removeEventListener("popstate", update); }, []);
  const navigate: Navigate = (next) => { const url = new URL(next, window.location.origin); window.history.pushState({}, "", url); setRoute({ path: formatRoute(url.pathname), search: url.search }); window.scrollTo({ top: 0, behavior: "smooth" }); };
  return { ...route, navigate };
}

function Link({ to, children, className, navigate }: { to: string; children: ReactNode; className?: string; navigate: Navigate }) {
  return <a href={to} className={className} onClick={(event) => { event.preventDefault(); navigate(to); }}>{children}</a>;
}

function usePropertyCatalog() {
  const [catalog, setCatalog] = useState<Property[]>(properties);
  const [status, setStatus] = useState(hasSupabaseConfig ? "Loading verified records from your independent database…" : "Showing the full labelled illustrative catalog until Supabase is configured.");
  const [loading, setLoading] = useState(hasSupabaseConfig);
  useEffect(() => {
    if (!hasSupabaseConfig) return;
    let active = true;
    fetchListings()
      .then(rows => { if (!active) return; setCatalog(mergeCatalog(rows)); setStatus(rows.length ? "Verified independent records are merged with the labelled UrbanKey demonstration catalog." : "No verified records are published yet; the labelled UrbanKey demonstration catalog is displayed."); })
      .catch(error => { if (!active) return; setStatus(error instanceof Error ? `The independent catalog service is unavailable: ${error.message}` : "The independent catalog service is unavailable."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);
  return { catalog, status, loading };
}

function Header({ navigate, path, search, marketId, setMarketId, locale, setLocale }: { navigate: Navigate; path: string; search: string; marketId: MarketId; setMarketId: (value: MarketId) => void; locale: LocaleId; setLocale: (value: LocaleId) => void }) {
  const [open, setOpen] = useState(false);
  const close = (destination: string) => { setOpen(false); navigate(destination); };
  const nav = [
    [translate(locale, "buy"), `/explore?marketId=${marketId}&mode=Buy`], [translate(locale, "rent"), `/explore?marketId=${marketId}&mode=Rent`], [translate(locale, "commercial"), `/explore?marketId=${marketId}&propertyType=Office`], [translate(locale, "map"), `/map?marketId=${marketId}`], [translate(locale, "concierge"), "/assistants"], [translate(locale, "agent"), "/property-agent"],
  ] as const;
  const isActive = (destination: string) => {
    const target = new URL(destination, window.location.origin);
    if (path !== target.pathname) return false;
    if (!target.search) return true;
    const current = new URLSearchParams(search);
    const expected = new URLSearchParams(target.search);
    return [...expected.entries()].every(([key, value]) => current.get(key) === value);
  };
  const chooseMarket = (nextMarket: MarketId) => { setMarketId(nextMarket); close(`/explore?marketId=${nextMarket}`); };
  return <header className="header"><a href="/" className="brand" onClick={(event) => { event.preventDefault(); close("/"); }}><i><Building2 size={21}/></i><span>UrbanKey<small>{marketNames[marketId]}</small></span></a><button className="menu" onClick={() => setOpen(current => !current)} aria-label="Open navigation">{open ? <X /> : <Menu />}</button><nav className={open ? "open" : ""}>{nav.map(([label, destination]) => <a key={label} aria-current={isActive(destination) ? "page" : undefined} className={isActive(destination) ? "active" : undefined} href={destination} onClick={(event) => { event.preventDefault(); close(destination); }}>{label}</a>)}<a href="/agent" className="nav-cta" onClick={(event) => { event.preventDefault(); close("/agent"); }}>{translate(locale, "portal")}</a></nav><div className="market-language"><label><span>{translate(locale, "market")}</span><select aria-label="Choose active property market" value={marketId} onChange={event => chooseMarket(event.target.value as MarketId)}>{markets.map(market => <option key={market.id} value={market.id}>{market.countryCode} · {market.name}</option>)}</select></label><label><span>{translate(locale, "language")}</span><select aria-label="Choose display language" value={locale} onChange={event => setLocale(event.target.value as LocaleId)}>{locales.map(item => <option key={item.id} value={item.id}>{item.nativeLabel}</option>)}</select></label></div><AuthStatus /></header>;
}

function Footer({ navigate }: { navigate: Navigate }) {
  return <footer><div><strong>UrbanKey</strong><span>Singapore property, understood.</span></div><div className="footer-links"><Link to="/explore" navigate={navigate}>Explore</Link><Link to="/map" navigate={navigate}>Map intelligence</Link><Link to="/property-agent" navigate={navigate}>Property Agent</Link><Link to="/agent" navigate={navigate}>Agent portal</Link></div><p>Independent Vercel application. All catalogue records are illustrative unless clearly marked as independently verified. Verify information before acting.</p></footer>;
}

function PropertyCard({ property, navigate }: { property: Property; navigate: Navigate }) {
  return <article className="property-card"><div className={`property-image ${property.tone}`}><img className="property-photo" src={property.image} alt={`${property.title} illustrative listing visual`} /><span className="pill">{property.category === "Commercial" ? "Commercial" : property.mode}</span>{property.virtualTourAvailable && <span className="tour-available">Virtual tour</span>}<button className="save-control" aria-label={`Save ${property.title}`} onClick={() => navigate(`/property/${property.id}`)}><Heart size={14} /></button><div><span>{property.type}</span><strong>{property.district}</strong></div></div><div className="property-copy"><p className="demo-label">{property.planningDemo ? "Future-market planning demo" : "Illustrative listing · verification required"}</p><h3>{property.title}</h3><p className="address">{property.address}</p><p className="price">{displayPrice(property)}</p><div className="specs"><span><BedDouble size={15} />{property.beds || "Commercial"}</span><span><Bath size={15} />{property.baths} bath</span><span>{property.size.toLocaleString("en-SG")} sq ft</span></div><div className="tags">{property.tags.slice(0, 3).map(tag => <span key={tag}>{tag}</span>)}</div><button className="text-link" onClick={() => navigate(`/property/${property.id}`)}>View property profile <ArrowRight size={15} /></button></div></article>;
}

