function readExploreFilters(): CatalogFilters {
  const params = new URLSearchParams(window.location.search);
  const numeric = (key: string) => { const value = params.get(key); return value ? Number(value) : undefined; };
  return { marketId: (params.get("marketId") as MarketId | null) ?? "singapore", mode: (params.get("mode") as ListingMode | null) ?? "Buy", search: params.get("search") ?? "", district: params.get("district") ?? "All districts", propertyType: params.get("propertyType") ?? "All types", tenure: params.get("tenure") ?? "Any ownership", maxPrice: numeric("maxPrice"), minSize: numeric("minSize"), maxMrtMinutes: numeric("maxMrtMinutes"), commercialUsage: params.get("commercialUsage") ?? "Any usage", minFloorLoading: numeric("minFloorLoading"), minCeilingHeight: numeric("minCeilingHeight") };
}

function ExplorePage({ navigate }: { navigate: Navigate }) {
  const [filters, setFilters] = useState<CatalogFilters>(readExploreFilters);
  const { catalog, status, loading } = usePropertyCatalog();
  const visible = useMemo(() => filterCatalog(catalog, filters), [catalog, filters]);
  const commercialFocus = hasCommercialFocus(filters.propertyType);
  const set = <K extends keyof CatalogFilters>(key: K, value: CatalogFilters[K]) => setFilters(current => ({ ...current, [key]: value }));
  useEffect(() => { const encoded = filtersToSearch(filters); window.history.replaceState({}, "", `/explore${encoded ? `?${encoded}` : ""}`); }, [filters]);
  const market = filters.marketId ?? "singapore";
  return <section className="page explore-page"><div className="page-title"><p className="eyebrow">Property marketplace</p><h1>Explore {marketNames[market]} spaces.</h1><p>Search the full UrbanKey demonstration catalog and independently published records with the same route-backed discovery controls.</p></div><div className="explore-filter-card"><div className="filter-primary"><label className="filter-search"><Search size={17} /><input value={filters.search ?? ""} onChange={event => set("search", event.target.value)} placeholder="Property, district, MRT or street" /></label><FilterSelect label="Listing mode" value={filters.mode ?? "Buy"} onChange={value => set("mode", value as ListingMode)} options={singaporeModes.map(item => [item.value, item.label])} /><FilterSelect label="District" value={filters.district ?? "All districts"} onChange={value => set("district", value)} options={[["All districts", "All districts"], ...singaporeDistricts.map(item => [item, item])]} /><FilterSelect label="Property type" value={filters.propertyType ?? "All types"} onChange={value => set("propertyType", value)} options={[["All types", "All types"], ...propertyTypes.map(item => [item, item])]} /><FilterSelect label="Ownership" value={filters.tenure ?? "Any ownership"} onChange={value => set("tenure", value)} options={[["Any ownership", "Any ownership"], ["Freehold", "Freehold"], ["99-year", "99-year"], ["60-year", "60-year"], ["30-year", "30-year"]]} /><FilterSelect label="Minimum area" value={filters.minSize ? String(filters.minSize) : ""} onChange={value => set("minSize", value ? Number(value) : undefined)} options={[["", "Any size"], ["1000", "1,000+ sq ft"], ["5000", "5,000+ sq ft"], ["20000", "20,000+ sq ft"], ["50000", "50,000+ sq ft"]]} /><FilterSelect label="MRT walk" value={filters.maxMrtMinutes ? String(filters.maxMrtMinutes) : ""} onChange={value => set("maxMrtMinutes", value ? Number(value) : undefined)} options={[["", "Any distance"], ["5", "Within 5 min"], ["10", "Within 10 min"], ["15", "Within 15 min"]]} /></div>{commercialFocus && <div className="commercial-filter-row"><div><p className="eyebrow">Commercial filters</p><span>Operational fields are shown only where they are relevant to commercial records.</span></div><FilterSelect label="Commercial usage" value={filters.commercialUsage ?? "Any usage"} onChange={value => set("commercialUsage", value)} options={[["Any usage", "Any usage"], ["Office", "Office"], ["Retail", "Retail"], ["F&B", "F&B"], ["Warehouse", "Warehouse"], ["Factory", "Factory"]]} /><FilterSelect label="Minimum loading" value={filters.minFloorLoading ? String(filters.minFloorLoading) : ""} onChange={value => set("minFloorLoading", value ? Number(value) : undefined)} options={[["", "Any loading"], ["5", "5+ kN/m²"], ["10", "10+ kN/m²"], ["20", "20+ kN/m²"], ["30", "30+ kN/m²"]]} /><FilterSelect label="Minimum height" value={filters.minCeilingHeight ? String(filters.minCeilingHeight) : ""} onChange={value => set("minCeilingHeight", value ? Number(value) : undefined)} options={[["", "Any height"], ["3", "3+ m"], ["6", "6+ m"], ["10", "10+ m"], ["12", "12+ m"]]} /></div>}</div><div className="explore-summary"><div><b>{visible.length}</b> properties matched <span>· {status}</span></div><FilterSelect label="Maximum price" value={filters.maxPrice ? String(filters.maxPrice) : ""} onChange={value => set("maxPrice", value ? Number(value) : undefined)} options={[["", "Any price"], ["25000", "Up to S$25,000"], ["75000", "Up to S$75,000"], ["150000", "Up to S$150,000"], ["5000000", "Up to S$5m"], ["15000000", "Up to S$15m"], ["50000000", "Up to S$50m"]]} /></div>{loading ? <div className="property-grid skeleton-grid">{[1, 2, 3].map(item => <div className="property-skeleton" key={item} />)}</div> : visible.length ? <>{visible.some(item => item.planningDemo) && <div className="notice"><ShieldCheck size={18} /><span><b>Future-market planning demo.</b> Planning-demo inventory is not live, available, or verified and must not be used to assess price, availability, ownership, or local market conditions.</span></div>}<div className="property-grid">{visible.map(property => <PropertyCard key={property.id} property={property} navigate={navigate} />)}</div></> : <div className="empty"><Search size={24} /><h2>No matching property profile</h2><p>Try another term or relax a filter. You can also start a shortlist with the AI concierge.</p><button className="dark-button" onClick={() => navigate("/assistants")}>Ask the concierge</button></div>}</section>;
}

function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[][] }) {
  return <label className="filter-select"><span>{label}</span><select aria-label={label} value={value} onChange={event => onChange(event.target.value)}>{options.map(([optionValue = "", name = "" ]) => <option key={`${optionValue}-${name}`} value={optionValue}>{name}</option>)}</select></label>;
}

function PropertyPage({ id, navigate }: { id: string; navigate: Navigate }) {
  const { catalog, loading } = usePropertyCatalog();
  const [activeGallery, setActiveGallery] = useState(0);
  const [galleryOpen, setGalleryOpen] = useState(false);
  const property = catalog.find(item => item.id === id);
  useEffect(() => setActiveGallery(0), [id]);
  if (loading && !property) return <section className="page"><div className="detail-loading" /></section>;
  if (!property) return <section className="auth-page"><div className="auth-card"><p className="eyebrow">Property profile</p><h1>Property not found.</h1><p>This record may no longer be present in the independent catalog. It was not replaced with another listing.</p><button className="dark-button" onClick={() => navigate("/explore")}>Return to properties</button></div></section>;
  const specifications = property.category === "Commercial"
    ? [[Ruler, `${property.size.toLocaleString("en-SG")} sq ft`], [Gauge, `${property.floorLoading ?? "—"} kN/m² loading`], [Layers3, `${property.ceilingHeight ?? "—"} m ceiling`], [Warehouse, `${property.parkingLots ?? 0} parking lots`]]
    : [[BedDouble, `${property.beds} bedrooms`], [Bath, `${property.baths} bathrooms`], [Ruler, `${property.size.toLocaleString("en-SG")} sq ft`], [TrainFront, `${property.minutes} min to MRT`]];
  const guideLabel = isRental(property) ? "Guide rent" : "Guide price";
  return <section className="page property-detail"><div className="detail-actions"><button className="back" onClick={() => navigate("/explore")}>← Back to explore</button><div><button className="icon-text" onClick={() => navigator.clipboard?.writeText(window.location.href)}> <Share2 size={15} />Share</button><SaveFavouriteButton listingId={property.id} className="icon-text" /></div></div><section className="gallery-grid"><button className="gallery-primary" aria-label={`Open ${property.title} image gallery`} onClick={() => setGalleryOpen(true)}><img src={property.gallery[activeGallery] ?? property.image} alt={property.title} /><span><ScanLine size={16} />View gallery</span></button>{property.gallery.slice(1, 3).map((image, index) => <button className="gallery-secondary" key={`${image}-${index}`} onClick={() => setActiveGallery(index + 1)}><img src={image} alt={`${property.title} view ${index + 2}`} /></button>)}</section><section className="detail-layout rich-detail"><div><div className="property-title-row"><div><p className="eyebrow">{property.type} · {property.tenure}</p><h1>{property.title}</h1><p className="detail-location"><MapPin size={16} />{property.address} · {property.district}</p></div><div className="price-panel"><span>{guideLabel}</span><b>{displayPrice(property)}</b><small>{displayPricePerArea(property)}</small></div></div><div className="detail-spec-grid">{specifications.map(([Icon, label]) => { const IconComponent = Icon as typeof Ruler; return <div key={label as string}><IconComponent size={20} /><span>{label as string}</span></div>; })}</div>{property.category === "Commercial" && <section className="commercial-detail"><div><span>Approved / intended use</span><b>{property.commercialUsage}</b></div><div><span>Loading access</span><b>{property.loadingAccess}</b></div><div><span>Available from</span><b>{property.availableFrom ?? "By arrangement"}</b></div></section>}<p className="body-copy detail-description">{property.detail}</p><div className="tags">{property.tags.map(tag => <span key={tag}>{tag}</span>)}</div>{property.virtualTourAvailable && <section className="virtual-tour-note"><ScanLine size={20} /><div><p className="eyebrow">Virtual Property Tour</p><b>Illustrative guided viewing media is available.</b><span>It is not a real property survey or a 3D floor-plan model. Request an in-person viewing to verify all conditions.</span></div><button className="outline-button" onClick={() => document.getElementById("tour-viewer")?.scrollIntoView({ behavior: "smooth", block: "start" })}>View details</button></section>}<VirtualTour property={property} onRequestViewing={() => document.querySelector(".action-card")?.scrollIntoView({ behavior: "smooth", block: "start" })} /><section id="tour-note" className="history-block"><div><p className="eyebrow">Property intelligence</p><h2>Context before you decide.</h2></div><div className="transaction-list">{property.transactions.length ? property.transactions.map(transaction => <div key={`${transaction.date}-${transaction.unit}`}><span>{transaction.date} · {transaction.type}</span><b>{transaction.unit}</b><span>S${transaction.price.toLocaleString("en-SG")} · S${transaction.psf.toLocaleString("en-SG")} PSF</span></div>) : <p>This future-market planning record has no transaction history.</p>}</div></section></div><aside className="action-card"><EnquiryForm listingId={property.id} listingTitle={property.title} /><button className="outline-button" onClick={() => navigate(`/map?property=${property.id}`)}>View area context</button><button className="outline-button" onClick={() => navigate("/assistants")}>Ask AI about this property</button></aside></section>{galleryOpen && <GalleryModal property={property} active={activeGallery} onActive={setActiveGallery} onClose={() => setGalleryOpen(false)} />}</section>;
}

function GalleryModal({ property, active, onActive, onClose }: { property: Property; active: number; onActive: (index: number) => void; onClose: () => void }) {
  return <div role="dialog" aria-modal="true" aria-label={`${property.title} gallery`} className="gallery-modal"><div><div className="gallery-modal-top"><span><p className="eyebrow">Property gallery</p><b>{property.title}</b></span><button aria-label="Close gallery" onClick={onClose}><X /></button></div><div className="gallery-modal-image"><img src={property.gallery[active] ?? property.image} alt={`${property.title} full view ${active + 1}`} /><button aria-label="Previous image" onClick={() => onActive((active - 1 + property.gallery.length) % property.gallery.length)}><ChevronLeft /></button><button aria-label="Next image" onClick={() => onActive((active + 1) % property.gallery.length)}><ChevronRight /></button></div></div></div>;
}

function MapPage({ navigate, marketId }: { navigate: Navigate; marketId: MarketId }) {
  const { catalog, status } = usePropertyCatalog();
  const params = new URLSearchParams(window.location.search);
  const initial = catalog.find(item => item.id === params.get("property")) ?? null;
  const [selectedId, setSelectedId] = useState<string | null>(initial?.id ?? null);
  const [showDistricts, setShowDistricts] = useState(true);
  const [showMrt, setShowMrt] = useState(true);
  const marketProperties = catalog.filter(item => item.marketId === marketId);
  const selected = marketProperties.find(item => item.id === selectedId) ?? null;
  const select = (property: Property) => { setSelectedId(property.id); window.history.replaceState({}, "", `/map?property=${property.id}`); };
  return <section className="page map-page"><div className="page-title"><p className="eyebrow">Map intelligence</p><h1>Use context before you commit.</h1><p>View the configured {marketNames[marketId]} map and the independently maintained listing catalog together. Map layers are decision-support aids, not verified property data.</p></div><div className="map-intelligence-shell"><div className="map-canvas live-map-canvas"><GoogleMapSurface marketId={marketId} focus={selected ? { latitude: selected.latitude, longitude: selected.longitude, title: selected.title } : undefined} /><div className="map-overlay-legend"><span><i />Homes</span><span><i className="commercial" />Commercial</span><span>{marketProperties.length} catalog points</span></div></div><aside className="map-control-panel"><p className="eyebrow">Area snapshot</p><h2>{selected?.district ?? marketNames[marketId]}</h2><p>{status}</p><div className="layer-toggles"><label><span><Layers3 size={16} />{marketId === "singapore" ? "District boundaries" : "Market context"}</span><input type="checkbox" checked={showDistricts} onChange={event => setShowDistricts(event.target.checked)} /></label><label><span><TrainFront size={16} />{marketId === "singapore" ? "MRT travel context" : "Transit context"}</span><input type="checkbox" checked={showMrt} onChange={event => setShowMrt(event.target.checked)} /></label></div><div className="map-point-list">{marketProperties.slice(0, 8).map(property => <button key={property.id} className={selected?.id === property.id ? "selected" : ""} onClick={() => select(property)}><span className={property.category === "Commercial" ? "commercial-dot" : "home-dot"} /><span><b>{property.title}</b><small>{property.district} · {displayPrice(property)}</small></span></button>)}</div>{selected && <div className="map-selection-card"><img src={selected.image} alt="" /><div><p>{selected.type} · {selected.district}</p><h3>{selected.title}</h3><span>{selected.category === "Commercial" ? selected.commercialUsage : `${selected.beds} bedrooms · ${selected.size.toLocaleString("en-SG")} sq ft`}</span><button className="dark-button" onClick={() => navigate(`/property/${selected.id}`)}>View property <ArrowRight size={15} /></button></div></div>}<button className="outline-button map-recenter" onClick={() => { setSelectedId(null); window.history.replaceState({}, "", `/map?marketId=${marketId}`); }}><LocateFixed size={15} />Recenter {marketNames[marketId]}</button><p className="map-disclosure">{showDistricts ? "Market context enabled. " : "Market context hidden. "}{showMrt ? "Transit context enabled." : "Transit context hidden."}{marketId !== "singapore" ? " This selected country uses live standard Google Maps until a country-specific 3D Map ID is published." : ""}</p></aside></div></section>;
}

function AssistantsPage({ navigate }: { navigate: Navigate }) {
  const [mode, setMode] = useState<"buyer" | "agent">("buyer");
  const prompts = mode === "buyer" ? ["Shortlist homes", "Prepare a viewing brief", "Compare commercial spaces", "Explain next paperwork step"] : ["Organise a buyer brief", "Prepare a viewing draft", "Create a document checklist", "Explain authorisation gates"];
  const [messages, setMessages] = useState<{ role: "user" | "assistant"; content: string }[]>([{ role: "assistant", content: "I can organise an illustrative shortlist, explain the information to prepare, and keep approval requirements visible. I do not contact owners, submit paperwork, or give legal, financial, or regulatory advice." }]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const send = async (question: string) => {
    const message = question.trim(); if (!message || busy) return;
    setMessages(current => [...current, { role: "user", content: message }]); setInput(""); setBusy(true);
    try {
      const response = await fetch("/api/assistant", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ mode, messages: [...messages, { role: "user", content: message }].slice(-8) }) });
      const result = await response.json() as { answer?: string; error?: string };
      setMessages(current => [...current, { role: "assistant", content: result.answer ?? result.error ?? "The secure assistant is not available right now. You can still use the catalogue and approval-controlled Property Agent workflow." }]);
    } catch { setMessages(current => [...current, { role: "assistant", content: "The secure assistant is unavailable. No request was sent to a property owner or external party." }]); }
    finally { setBusy(false); }
  };
  return <section className="page assistant-page"><div className="assistant-shell"><aside><p className="eyebrow">UrbanKey concierge</p><h2>A calmer path through property decisions.</h2><p>Choose a role, then use a secure server route for bounded, non-advisory assistance.</p><div className="assistant-modes"><button className={mode === "buyer" ? "selected" : ""} onClick={() => { setMode("buyer"); setMessages([{ role: "assistant", content: "Buyer / tenant mode is active. I can help structure a shortlist and prepare for a human-reviewed next step." }]); }}>Buyer / tenant</button><button className={mode === "agent" ? "selected" : ""} onClick={() => { setMode("agent"); setMessages([{ role: "assistant", content: "Agent / co-broker mode is active. I can organise non-binding drafts and highlight approvals required before external action." }]); }}>Agent / co-broker</button></div>{prompts.map(prompt => <button key={prompt} onClick={() => void send(prompt)}>{prompt}<ChevronRight size={16} /></button>)}</aside><div className="assistant-chat"><div className="chat-top"><span><Bot size={19} />AI Concierge</span><b>Secure workflow</b></div><div className="chat-body" aria-live="polite">{messages.map((message, index) => <div className={`bubble ${message.role === "user" ? "user" : "bot"}`} key={`${message.role}-${index}`}>{message.content}</div>)}{busy && <div className="bubble bot">Preparing a bounded response…</div>}<div className="action-row"><button onClick={() => navigate("/explore")}>Explore listings</button><button onClick={() => navigate("/property-agent")}>Open Property Agent</button></div></div><form className="chat-input" onSubmit={event => { event.preventDefault(); void send(input); }}><input value={input} onChange={event => setInput(event.target.value)} maxLength={1000} placeholder="Ask about the next property step" /><button aria-label="Send message" disabled={busy || !input.trim()}><ArrowRight size={17} /></button></form></div></div></section>;
}

function PropertyAgentPage({ navigate }: { navigate: Navigate }) {
  const [journey, setJourney] = useState<PropertyAgentCase["journey"]>("buy");
  const [requirements, setRequirements] = useState("");
  const [consent, setConsent] = useState(false);
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);
  const create = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setStatus(""); try { const id = await createPropertyAgentCase({ journey, requirements, consent }); setStatus(`Your private ${journey.replace("_", " ")} case was created with recorded processing consent. Case reference: ${id.slice(0, 8)}.`); setRequirements(""); } catch (error) { setStatus(error instanceof Error ? error.message : "Unable to create the protected case."); } finally { setBusy(false); } };
  return <section className="page"><div className="page-title agent-title"><p className="eyebrow">Property Agent</p><h1>Coordinate the work. Keep decisions with people.</h1><p>Start a private Singapore workflow, structure next steps, prepare non-binding drafts, and route authorised matters to appropriate professionals—without sending, filing, or committing anything for you.</p></div><div className="agent-steps">{agentSteps.map(([number, title, copy]) => <article key={number}><span>{number}</span><h2>{title}</h2><p>{copy}</p></article>)}</div><div className="agent-grid"><article><FileCheck2 /><h2>Paperwork readiness</h2><p>Prepare checklists and document requests. Secure identity, signature, legal review, and official submissions remain in verified human processes.</p></article><article><CalendarCheck /><h2>Viewing coordination</h2><p>Organise suggested steps and drafts only after the responsible user grants approval.</p></article><article><UsersRound /><h2>Professional hand-offs</h2><p>Structure briefs for lawyers, lenders, owners, agents, and government touchpoints without impersonating any party.</p></article></div><div className="property-agent-shell"><form className="case-form" onSubmit={create}><p className="eyebrow">Create a private case</p><h2>Start with explicit consent.</h2><label>Journey<select value={journey} onChange={event => setJourney(event.target.value as PropertyAgentCase["journey"])}><option value="buy">Buy a property</option><option value="sell">Sell a property</option><option value="rent">Rent a property</option><option value="rent_out">Lease out a property</option></select></label><label>Requirements, target area, budget, or timing<textarea value={requirements} required minLength={1} maxLength={4000} onChange={event => setRequirements(event.target.value)} placeholder="Describe what you want to prepare. Do not add sensitive documents here." /></label><label className="checkline"><input type="checkbox" checked={consent} onChange={event => setConsent(event.target.checked)} /><span>I consent to UrbanKey recording this request and creating the private workflow material described above. I understand that no external action will occur without my explicit authorisation.</span></label><button className="dark-button" disabled={!consent || busy}>{busy ? "Creating protected case…" : "Create approval-controlled case"}<ArrowRight size={16} /></button>{status && <p className="form-status" role="status">{status}</p>}</form><aside className="safeguard-card"><ShieldCheck size={24} /><h2>Authorisation safeguard</h2><p>{propertyAgentSafeguardNotice}</p><button className="outline-button" onClick={() => navigate("/dashboard")}>Review my cases</button></aside></div></section>;
}

function AgentLogin({ navigate }: { navigate: Navigate }) {
  return <section className="auth-page"><div className="auth-card"><p className="eyebrow">Agent portal</p><h1>Sign in securely.</h1><p>Use a Supabase email magic link to access your independent UrbanKey account. Once signed in, complete the professional profile and wait for verification before managing live listings.</p><AuthStatus /><button className="dark-button" onClick={() => navigate("/agent/portal")}>Open workspace <ArrowRight size={16} /></button><Link to="/agent/signup" navigate={navigate}>Register Agent / Co-broker profile</Link><Link to="/property-agent" navigate={navigate}>Start a Property Agent request</Link></div></section>;
}

function AgentSignUp({ navigate }: { navigate: Navigate }) {
  const [form, setForm] = useState({ professionalType: "agent" as "agent" | "cobroker", companyName: "", licenceNumber: "", phone: "", postalCode: "", terms: false });
  const [status, setStatus] = useState(""); const [busy, setBusy] = useState(false);
  const update = <K extends keyof typeof form>(key: K, value: typeof form[K]) => setForm(current => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setStatus(""); try { if (!/^\d{6}$/.test(form.postalCode)) throw new Error("Enter a valid Singapore six-digit postal code."); if (!form.terms) throw new Error("Accept the professional terms before registering."); await registerAgentProfile({ professional_type: form.professionalType, company_name: form.companyName.trim(), licence_number: form.licenceNumber.trim(), phone: form.phone.trim(), postal_code: form.postalCode }); setStatus("Professional profile submitted. It remains pending until an authorised administrator verifies the registration."); } catch (error) { setStatus(error instanceof Error ? error.message : "Unable to submit the professional profile."); } finally { setBusy(false); } };
  return <section className="auth-page"><form className="auth-card signup-card" onSubmit={submit}><p className="eyebrow">Agent / Co-broker registration</p><h1>Set up the professional workspace.</h1><p>Registration does not grant a role automatically. An independent administrator verifies the licence before a listing can be activated.</p><label>Professional role<select value={form.professionalType} onChange={event => update("professionalType", event.target.value as "agent" | "cobroker")}><option value="agent">Agent</option><option value="cobroker">Co-broker</option></select></label><label>Company<input required minLength={2} maxLength={160} value={form.companyName} onChange={event => update("companyName", event.target.value)} /></label><label>Licence / registration number<input required minLength={3} maxLength={80} value={form.licenceNumber} onChange={event => update("licenceNumber", event.target.value)} /></label><label>Contact number<input required minLength={6} maxLength={40} value={form.phone} onChange={event => update("phone", event.target.value)} /></label><label>Singapore postal code<input required inputMode="numeric" pattern="[0-9]{6}" value={form.postalCode} onChange={event => update("postalCode", event.target.value.replace(/\D/g, "").slice(0, 6))} /></label><label className="checkline"><input type="checkbox" checked={form.terms} onChange={event => update("terms", event.target.checked)} /><span>I confirm that my professional details are accurate and I will not use UrbanKey to make commitments or submit records without authority.</span></label><button className="dark-button" disabled={busy}>{busy ? "Submitting…" : "Submit for verification"}<ArrowRight size={16} /></button>{status && <p className="form-status" role="status">{status}</p>}<Link to="/agent" navigate={navigate}>Return to sign in</Link></form></section>;
}

function AgentPortal({ navigate }: { navigate: Navigate }) {
  const [profile, setProfile] = useState<AgentProfile | null>(null);
  const [listings, setListings] = useState<LiveListing[]>([]);
  const [status, setStatus] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const load = async () => { try { const [agentProfile, ownedListings] = await Promise.all([getAgentProfile(), fetchManagedListings()]); setProfile(agentProfile); setListings(ownedListings); setStatus(""); } catch (error) { setStatus(error instanceof Error ? error.message : "Sign in to view the private workspace."); } };
  useEffect(() => { void load(); }, []);
  return <section className="dashboard-page"><div className="dash-sidebar"><p className="eyebrow">Agent workspace</p><h2>UrbanKey<br />Agent Portal</h2><button className="selected" onClick={() => void load()}>Listings</button><button onClick={() => navigate("/agent/tours")}>Tour quality check</button><button onClick={() => navigate("/dashboard")}>My dashboard</button><button className="sidebar-link" onClick={() => navigate("/agent/signup")}>Professional profile</button></div><main className="dash-main"><div className="dash-top"><div><p className="eyebrow">Portfolio</p><h1>Your secure workspace.</h1><p>Listings remain draft-only until a verified professional activates them through the independent administration process.</p></div><button className="gold-button" onClick={() => setShowCreate(current => !current)}>Create draft listing <ArrowRight size={16} /></button></div>{profile && <div className={`verification-banner ${profile.verification_status}`}><BadgeCheck size={18} /><span><b>{profile.professional_type === "agent" ? "Agent" : "Co-broker"} profile: {profile.verification_status}</b> · {profile.company_name} · {profile.licence_number}</span></div>}{status && <p className="form-status workspace-status">{status}</p>}{showCreate && <ListingForm onCreated={() => { setShowCreate(false); void load(); }} /> }<section className="portfolio-list"><div className="portfolio-heading"><h2>My listings</h2><span>{listings.length} record{listings.length === 1 ? "" : "s"}</span></div>{listings.length ? listings.map(listing => <article key={listing.id}><img src={listing.image_url ?? "/assets/office-building_b7b74f98.jpg"} alt="" /><div><p>{listing.property_type} · {listing.district}</p><h3>{listing.title}</h3><span>{listing.price_label} · {listing.listing_status ?? (listing.is_published ? "active" : "draft")}</span></div></article>) : <div className="empty"><Building2 size={24} /><h2>No private listings yet</h2><p>Complete a verified Agent / Co-broker profile, then create a draft record here. No public listing is created automatically.</p></div>}</section></main></section>;
}

function ListingForm({ onCreated }: { onCreated: () => void }) {
  const [form, setForm] = useState<ManagedListingInput>({ title: "", district: "D01 · Marina Bay", address: "", propertyType: "Condominium", mode: "Buy", price: 0, size: 0, tenure: "99-year", bedrooms: 2, bathrooms: 2, description: "" });
  const [status, setStatus] = useState(""); const [busy, setBusy] = useState(false);
  const update = <K extends keyof ManagedListingInput>(key: K, value: ManagedListingInput[K]) => setForm(current => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setStatus(""); try { await createManagedListing(form); onCreated(); } catch (error) { setStatus(error instanceof Error ? error.message : "Unable to create the listing draft."); } finally { setBusy(false); } };
  return <form className="listing-form" onSubmit={submit}><p className="eyebrow">Private draft</p><h2>Create a listing record</h2><div className="listing-form-grid"><label>Title<input required minLength={3} value={form.title} onChange={event => update("title", event.target.value)} /></label><label>District<select value={form.district} onChange={event => update("district", event.target.value)}>{singaporeDistricts.map(district => <option key={district}>{district}</option>)}</select></label><label>Address<input required value={form.address} onChange={event => update("address", event.target.value)} /></label><label>Property type<select value={form.propertyType} onChange={event => update("propertyType", event.target.value)}>{propertyTypes.map(type => <option key={type}>{type}</option>)}</select></label><label>Mode<select value={form.mode} onChange={event => update("mode", event.target.value as ListingMode)}>{singaporeModes.map(mode => <option key={mode.value} value={mode.value}>{mode.label}</option>)}</select></label><label>Guide price (S$)<input required type="number" min="0" value={form.price || ""} onChange={event => update("price", Number(event.target.value))} /></label><label>Size (sq ft)<input required type="number" min="1" value={form.size || ""} onChange={event => update("size", Number(event.target.value))} /></label><label>Tenure<input required value={form.tenure} onChange={event => update("tenure", event.target.value)} /></label></div><label>Description<textarea required minLength={20} maxLength={4000} value={form.description} onChange={event => update("description", event.target.value)} /></label><button className="dark-button" disabled={busy}>{busy ? "Saving draft…" : "Save private draft"}<Check size={16} /></button>{status && <p className="form-status">{status}</p>}</form>;
}

function TourQuality({ navigate }: { navigate: Navigate }) {
  const [listings, setListings] = useState<LiveListing[]>([]); const [listingId, setListingId] = useState(""); const [file, setFile] = useState<File>(); const [roomLabel, setRoomLabel] = useState(""); const [authority, setAuthority] = useState(false); const [consent, setConsent] = useState(false); const [status, setStatus] = useState(""); const [busy, setBusy] = useState(false);
  useEffect(() => { fetchManagedListings().then(rows => { setListings(rows); setListingId(rows[0]?.id ?? ""); }).catch(error => setStatus(error instanceof Error ? error.message : "Sign in to load private listings.")); }, []);
  const upload = async () => { if (!file || !listingId) { setStatus("Choose one owned listing, a room label, and a JPEG or WebP capture first."); return; } setBusy(true); setStatus(""); try { await uploadTourMedia(file, listingId, { roomLabel, hasAuthority: authority, hasConsent: consent }); setStatus("Capture submitted to private review. It is not published and requires an independent approval step."); setFile(undefined); } catch (error) { setStatus(error instanceof Error ? error.message : "Unable to store the private capture."); } finally { setBusy(false); } };
  return <section className="page quality-page"><div className="page-title"><p className="eyebrow">Agent toolkit</p><h1>Capture quality review.</h1><p>Submit an owned-listing JPEG or WebP capture for private quality and privacy review. This is raw media intake only; it does not create any 3D model or publish a tour.</p></div><div className="quality-card"><div className="quality-icon"><House size={32} /></div><div><h2>Private 360° capture intake</h2><p>Before the file is stored, confirm authority and consent. A passed review becomes <b>approval required</b>; it is never published directly from this screen.</p><label>Owned listing<select value={listingId} onChange={event => setListingId(event.target.value)}><option value="">Choose a private listing</option>{listings.map(listing => <option key={listing.id} value={listing.id}>{listing.title}</option>)}</select></label><label>Room / area label<input value={roomLabel} maxLength={120} onChange={event => setRoomLabel(event.target.value)} placeholder="Living room" /></label><label>JPEG or WebP capture (max 20 MB)<input type="file" accept="image/jpeg,image/webp" onChange={event => setFile(event.target.files?.[0])} /></label><label className="checkline"><input type="checkbox" checked={authority} onChange={event => setAuthority(event.target.checked)} /><span>I have owner authority to upload this capture for review.</span></label><label className="checkline"><input type="checkbox" checked={consent} onChange={event => setConsent(event.target.checked)} /><span>I have recorded capture consent and reviewed the media for visible private information.</span></label><button className="dark-button" disabled={!authority || !consent || !file || !listingId || !roomLabel || busy} onClick={() => void upload()}><UploadCloud size={16} />{busy ? "Submitting…" : "Submit for private review"}</button><p className="form-status" role="status">{status}</p></div></div><button className="back" onClick={() => navigate("/agent/portal")}>← Return to portal</button></section>;
}

function Dashboard({ navigate }: { navigate: Navigate }) {
  const [data, setData] = useState<DashboardData | null>(null); const [status, setStatus] = useState(""); const [editing, setEditing] = useState(false);
  const load = async () => { try { setData(await getDashboardData()); setStatus(""); } catch (error) { setStatus(error instanceof Error ? error.message : "Sign in to load your private workspace."); } };
  useEffect(() => { void load(); }, []);
  const profile = data?.profile ?? null;
  return <section className="page"><div className="page-title dashboard-heading"><div><p className="eyebrow">Your UrbanKey space</p><h1>Keep your shortlist close.</h1><p>Private dashboard data is loaded only for the signed-in account. It is not a shared demo workspace.</p></div><button className="outline-button" onClick={() => void load()}>Refresh workspace</button></div>{status && <div className="notice"><ShieldCheck size={18} /><span>{status}</span></div>}{data && <><div className="persona-card"><div><p className="eyebrow">Persona</p><h2>{profile?.persona?.replace("_", " / ") ?? "Choose your workspace"}</h2><p>Set a persona to tailor your independent dashboard. Your role remains controlled by the server and cannot be changed here.</p></div><button className="outline-button" onClick={() => setEditing(current => !current)}>Update profile</button>{editing && <ProfileForm profile={profile} onSaved={() => { setEditing(false); void load(); }} />}</div><div className="metric-grid"><div><span>Saved homes</span><b>{data.saved.length}</b><small>Private favourites</small></div><div><span>Enquiries</span><b>{data.enquiries.length}</b><small>Human-review requests</small></div><div><span>Property Agent cases</span><b>{data.cases.length}</b><small>Consent-controlled workflows</small></div></div>{profile?.persona === "seller_landlord" || profile?.persona === "agent_cobroker" ? <div className="dashboard-portfolio"><div><h2>Portfolio</h2><p>Your independently managed listing records.</p></div><button className="dark-button" onClick={() => navigate("/agent/portal")}>Open listing workspace</button></div> : null}<div className="saved-grid">{data.saved.length ? data.saved.map(live => <article className="saved-listing" key={live.id}><img src={live.image_url ?? "/assets/office-interior_791afa97.jpg"} alt="" /><b>{live.title}</b><span>{live.district}</span></article>) : <div className="empty"><Heart size={24} /><h2>No saved independent listings</h2><p>Use a property profile to save a published listing after signing in.</p><button className="dark-button" onClick={() => navigate("/explore")}>Explore listings</button></div>}</div></>}</section>;
}

function ProfileForm({ profile, onSaved }: { profile: DashboardData["profile"]; onSaved: () => void }) {
  const [displayName, setDisplayName] = useState(profile?.display_name ?? ""); const [persona, setPersona] = useState<NonNullable<DashboardData["profile"]>["persona"]>(profile?.persona ?? "buyer_tenant"); const [district, setDistrict] = useState(profile?.district ?? ""); const [budget, setBudget] = useState(profile?.budget ?? ""); const [status, setStatus] = useState("");
  const save = async (event: FormEvent) => { event.preventDefault(); try { await saveProfile({ display_name: displayName, persona, district, budget }); onSaved(); } catch (error) { setStatus(error instanceof Error ? error.message : "Unable to save profile."); } };
  return <form className="profile-form" onSubmit={save}><label>Name<input required maxLength={160} value={displayName} onChange={event => setDisplayName(event.target.value)} /></label><label>Workspace<select value={persona ?? "buyer_tenant"} onChange={event => setPersona(event.target.value as NonNullable<DashboardData["profile"]>["persona"])}><option value="buyer_tenant">Buyer / tenant</option><option value="seller_landlord">Seller / landlord</option><option value="agent_cobroker">Agent / co-broker</option></select></label><label>Preferred district<input value={district ?? ""} onChange={event => setDistrict(event.target.value)} /></label><label>Budget note<input value={budget ?? ""} onChange={event => setBudget(event.target.value)} /></label><button className="dark-button">Save private profile</button>{status && <p className="form-status">{status}</p>}</form>;
}

function NotFound({ navigate }: { navigate: Navigate }) {
  return <section className="auth-page"><div className="auth-card"><p className="eyebrow">404</p><h1>That page is not available.</h1><p>Payments, Coworking, 3D floor plans, and all 3D model pages are deliberately not included in this independent deployment.</p><button className="dark-button" onClick={() => navigate("/")}>Return home</button></div></section>;
}

function App() {
  const { path, search, navigate } = useRoute();
  const { marketId, setMarketId, locale, setLocale } = useMarketPreferences();
  useEffect(() => {
    const requestedMarket = new URLSearchParams(search).get("marketId") as MarketId | null;
    if (requestedMarket && requestedMarket in marketNames && requestedMarket !== marketId) setMarketId(requestedMarket);
  }, [search, marketId, setMarketId]);
  let page: ReactNode;
  if (path === "/") page = <HomePage navigate={navigate} marketId={marketId} locale={locale} />;
  else if (path === "/explore") page = <ExplorePage navigate={navigate} />;
  else if (path.startsWith("/property/")) page = <PropertyPage id={path.split("/").pop() ?? ""} navigate={navigate} />;
  else if (path === "/map") page = <MapPage navigate={navigate} marketId={marketId} />;
  else if (path === "/assistants") page = <AssistantsPage navigate={navigate} />;
  else if (path === "/property-agent") page = <PropertyAgentPage navigate={navigate} />;
  else if (path === "/agent") page = <AgentLogin navigate={navigate} />;
  else if (path === "/agent/signup") page = <AgentSignUp navigate={navigate} />;
  else if (path === "/agent/portal") page = <AgentPortal navigate={navigate} />;
  else if (path === "/agent/tours") page = <TourQuality navigate={navigate} />;
  else if (path === "/dashboard") page = <Dashboard navigate={navigate} />;
  else page = <NotFound navigate={navigate} />;
  return <><Header navigate={navigate} path={path} search={search} marketId={marketId} setMarketId={setMarketId} locale={locale} setLocale={setLocale} />{page}<Footer navigate={navigate} /></>;
}

createRoot(document.getElementById("root")!).render(<App />);
